package edu.pe.cibertec.saibm.membresia.domain.model;
import java.time.*; import java.util.UUID;
public record MembershipAssignment(UUID id,String userId,UUID planId,String planCode,int planVersion,int reservationLimit,Instant validFrom,Instant validUntil,boolean active,String idempotencyKey,String requestHash,String legacyUserId){public MembershipAssignment{validFrom=validFrom==null?null:validFrom.truncatedTo(java.time.temporal.ChronoUnit.MICROS);validUntil=validUntil==null?null:validUntil.truncatedTo(java.time.temporal.ChronoUnit.MICROS);}public static MembershipAssignment create(UUID id,String user,UUID plan,String code,int version,int limit,Instant from,Instant until,String key,String hash,String legacy){if(user==null||user.isBlank()||plan==null||key==null||key.isBlank()||from==null)throw new IllegalArgumentException("Invalid assignment");return new MembershipAssignment(id,user,plan,code,version,limit,from,until,true,key,hash,legacy);}public boolean validAt(Instant at){return active&&!at.isBefore(validFrom)&&(validUntil==null||at.isBefore(validUntil));}public MembershipAssignment expire(){return new MembershipAssignment(id,userId,planId,planCode,planVersion,reservationLimit,validFrom,validUntil,false,idempotencyKey,requestHash,legacyUserId);}}
